import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

fused_gemm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_gemm_scale_bias_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    const float* scale,
    float* output,
    int batch_size,
    int in_features,
    int out_features) {

    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;

    if (row >= batch_size || col >= out_features)
        return;

    float sum = 0.0f;
    for (int k = 0; k < in_features; ++k) {
        sum += input[row * in_features + k] * weight[col * in_features + k];
    }
    sum += bias[col];
    sum *= scale[col];

    output[row * out_features + col] = sum;
}

torch::Tensor fused_gemm_scale_bias_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor scale) {

    auto batch_size = input.size(0);
    auto in_features = input.size(1);
    auto out_features = weight.size(0);

    auto output = torch::zeros({batch_size, out_features}, input.options());

    dim3 block(16, 16);
    dim3 grid((batch_size + block.x - 1) / block.x, (out_features + block.y - 1) / block.y);

    fused_gemm_scale_bias_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        scale.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_features,
        out_features);

    return output;
}
"""

fused_gemm_cpp_source = """
torch::Tensor fused_gemm_scale_bias_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor scale);
"""

fused_gemm = load_inline(
    name='fused_gemm',
    cpp_sources=fused_gemm_cpp_source,
    cuda_sources=fused_gemm_source,
    functions=['fused_gemm_scale_bias_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, scale_shape, eps=1e-5, momentum=0.1):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.weight = nn.Parameter(torch.Tensor(out_features, in_features))
        self.bias = nn.Parameter(torch.Tensor(out_features))
        self.scale = nn.Parameter(torch.randn(scale_shape))
        self.bn = nn.BatchNorm1d(out_features, eps=eps, momentum=momentum)

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        x = fused_gemm.fused_gemm_scale_bias_cuda(x, self.weight, self.bias, self.scale)
        return self.bn(x)
